  function applySheyakaConfig(config, slug) {
    var bag = window.__SHEYAKA_CONFIGS__;
    var remote = bag && bag[slug];
    if (!remote || typeof remote !== 'object' || Array.isArray(remote)) return;
    Object.keys(remote).forEach(function (key) {
      config[key] = remote[key];
    });
  }
  applySheyakaConfig(CONFIG, 'build-your-look');

  const ROOT_ID = 'sheyaka-byl';
  const CARD_ID = 'sheyaka-byl-card';
  const MODAL_ID = 'sheyaka-byl-modal';
  const STYLE_ID = 'sheyaka-byl-style';

  function detectLang() {
    const html = document.documentElement;
    const body = document.body;
    const lang =
      html.getAttribute('lang') ||
      (body && body.getAttribute('lang')) ||
      html.getAttribute('xml:lang') ||
      '';
    if (/^ar/i.test(lang)) return 'ar';
    if (/^en/i.test(lang)) return 'en';
    const dir =
      html.getAttribute('dir') || (body && body.getAttribute('dir')) || '';
    return dir.toLowerCase() === 'ltr' ? 'en' : 'ar';
  }

  let LANG = detectLang();
  let DIR = LANG === 'ar' ? 'rtl' : 'ltr';

  function t(value, vars) {
    let text = '';
    if (value && typeof value === 'object') {
      text = value[LANG] || value.ar || value.en || '';
    } else {
      text = value || '';
    }
    if (vars) {
      Object.keys(vars).forEach(function (key) {
        text = text.replace(new RegExp('\\{\\{' + key + '\\}\\}', 'g'), vars[key]);
      });
    }
    return text;
  }

  function refreshLang() {
    LANG = detectLang();
    DIR = LANG === 'ar' ? 'rtl' : 'ltr';
  }

  function storeIdentifier() {
    try {
      if (window.salla && salla.config && typeof salla.config.get === 'function') {
        const store = salla.config.get('store');
        if (store && store.id) return String(store.id);
      }
    } catch (e) {
      /* ignore */
    }
    return null;
  }

  function getPageInfo() {
    try {
      if (window.salla && salla.config && typeof salla.config.get === 'function') {
        return salla.config.get('page') || null;
      }
    } catch (e) {
      /* ignore */
    }
    return null;
  }

  function isCategoryPage() {
    const page = getPageInfo();
    if (page && (page.slug === 'product.index' || page.slug === 'category.index')) {
      return true;
    }
    return /\/c\d+(\/|$|\?)/.test(window.location.pathname);
  }

  function isProductPage() {
    const page = getPageInfo();
    if (page && page.slug === 'product.single') return true;
    return /\/p\d+(\/|$|\?)/.test(window.location.pathname);
  }

  function currentCategoryId() {
    const page = getPageInfo();
    if (page && page.id && (page.slug === 'product.index' || page.slug === 'category.index')) {
      return Number(page.id);
    }
    const match = window.location.pathname.match(/\/c(\d+)/);
    return match ? Number(match[1]) : null;
  }

  function shouldShowOnThisPage() {
    if (!isCategoryPage() || isProductPage()) return false;
    const allowed = CONFIG.showOnCategoryIds || [];
    if (!allowed.length) return false;
    const id = currentCategoryId();
    return id != null && allowed.map(Number).indexOf(Number(id)) !== -1;
  }

  function escapeHtml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function productImage(product) {
    if (!product) return '';
    const image = product.image;
    if (!image) return '';
    if (typeof image === 'string') return image;
    return image.url || image.thumbnail || '';
  }

  function productPrice(product) {
    if (!product) return 0;
    const sale = Number(product.sale_price);
    const base = Number(product.price);
    if (product.is_on_sale && sale > 0) return sale;
    if (sale > 0 && sale < base) return sale;
    return base > 0 ? base : 0;
  }

  function formatMoney(amount) {
    const n = Number(amount) || 0;
    const formatted = n.toLocaleString(LANG === 'ar' ? 'ar-SA' : 'en-US', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
    });
    return formatted + (LANG === 'ar' ? ' ر.س' : ' SAR');
  }

  function notify(type, message) {
    try {
      if (window.salla && salla.notify && typeof salla.notify[type] === 'function') {
        salla.notify[type](message);
        return;
      }
    } catch (e) {
      /* ignore */
    }
    if (type === 'error') console.error(message);
    else console.log(message);
  }

  function decodeOptionsAttr(raw) {
    return raw
      .replace(/&quot;/g, '"')
      .replace(/&#0?39;/g, "'")
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&');
  }

  function stepDigit(n) {
    if (LANG !== 'ar') return String(n);
    return String(n).replace(/\d/g, function (d) {
      return '٠١٢٣٤٥٦٧٨٩'[Number(d)];
    });
  }

  // If a slot's category was emptied after a catalogue rebuild, try these next.
  const CATEGORY_FALLBACKS = {
    327183774: [1835961503, 2011049884], // old shemagh → men / kids shemagh
    1835961503: [2011049884],
  };

  function fetchCategoryProductsOnce(categoryId) {
    const identifier = storeIdentifier();
    if (!identifier) return Promise.reject(new Error('No store identifier'));

    const url =
      'https://api.salla.dev/store/v1/products?per_page=' +
      encodeURIComponent(CONFIG.productsPerPage) +
      '&source=categories&source_value%5B%5D=' +
      encodeURIComponent(categoryId);

    return fetch(url, {
      headers: {
        'store-identifier': identifier,
        Accept: 'application/json',
      },
    })
      .then(function (response) {
        if (!response.ok) throw new Error('products HTTP ' + response.status);
        return response.json();
      })
      .then(function (payload) {
        return Array.isArray(payload && payload.data) ? payload.data : [];
      });
  }

  function fetchCategoryProducts(categoryId) {
    const chain = [categoryId].concat(CATEGORY_FALLBACKS[categoryId] || []);
    let index = 0;

    function next() {
      if (index >= chain.length) return Promise.resolve([]);
      const id = chain[index];
      index += 1;
      return fetchCategoryProductsOnce(id).then(function (rows) {
        if (rows.length) return rows;
        return next();
      });
    }

    return next();
  }

  function fetchProductOptions(product) {
    const url = product && (product.url || product.permalink);
    if (!url) return Promise.resolve([]);

    return fetch(url, { credentials: 'same-origin' })
      .then(function (response) {
        if (!response.ok) throw new Error('product page HTTP ' + response.status);
        return response.text();
      })
      .then(function (html) {
        const match = /<salla-product-options[^>]*\soptions="([^"]*)"/.exec(html);
        if (!match) return [];
        try {
          const parsed = JSON.parse(decodeOptionsAttr(match[1]));
          return Array.isArray(parsed) ? parsed : [];
        } catch (e) {
          return [];
        }
      });
  }

